import React, { forwardRef } from 'react';
import styled from 'styled-components';

import { ActionGroup } from './action-group/ActionGroup.js';
import { useActionItemsContext } from './hooks/useActionItemsContext.js';
import { useNavItemsContext } from './hooks/useNavItemsContext.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

// #region Typings
// ESLint disabled in order for API extractor not to complain about exporting
// With children from the package
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface AppHeaderActionItemsProps
  extends WithChildren,
    StylingProps,
    DataTestId {}
// #endregion

// #region Styled Components
const StyledActionItems = styled(ActionGroup)({
  display: 'flex',
  justifyContent: 'end',
  minWidth: 0,
});
// #endregion

/**
 * The action items section of the AppHeader, which collapses into an overlay on small screen sizes.
 */
export const ActionItems = forwardRef<
  HTMLDivElement,
  AppHeaderActionItemsProps
>(
  (
    {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    },
    forwardedRef,
  ) => {
    const { setIsActionItemsCollapsed } = useActionItemsContext();
    const { isNavOverflowing } = useNavItemsContext();

    return (
      <StyledActionItems
        data-testid={dataTestId}
        ref={forwardedRef}
        collapsible={!!React.Children.toArray(children).length} // this makes the nav items collapsible even if there are no action items
        onCollapsedChange={setIsActionItemsCollapsed}
        flexItem
        flexGrow={isNavOverflowing ? 0 : 1}
        collapseFrom="end"
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </StyledActionItems>
    );
  },
);

(ActionItems as typeof ActionItems & { displayName: string }).displayName =
  'AppHeader.ActionItems';
